"""Stage 3 process runner. Results live in memory; this is not operation storage."""

import codecs
from datetime import datetime, timezone
import math
import os
import re
import threading
import time
from uuid import uuid4

from executor_config import ApiError, checked_path
from windows_job import WindowsJob


def timestamp():
    return datetime.now(timezone.utc).isoformat()


def sync_log(output):
    output.flush()
    os.fsync(output.fileno())


def is_interactive_launcher(command):
    # Only the constrained command generated by run_bat.py gets this exception.
    argument = r'(?:\s+"(?:(?:%CD%)|[^"%!&|<>^()\r\n])*")*'
    bat = r'run-(?:designer|enterprise)\.bat'
    script = r'(?:"(?:\.\.[\\/])?scripts[\\/]' + bat + r'"|(?:\.\.[\\/])?scripts[\\/]' + bat + r')'
    return bool(re.fullmatch(r'\s*(?:cd /d "[^"%!&|<>^()\r\n]+" && )?call ' + script + argument + r'\s*', command, re.IGNORECASE))


class ProcessRun:
    def __init__(self, project_id, command, log_path, persist=None, finalize=None, job_name=None, fault=None):
        self.log_path = log_path
        self._lock = threading.Lock()
        self._cancel = threading.Event()
        self._done = threading.Event()
        self._started = threading.Event()
        self._failure = None
        self._persist = persist
        self._finalize = finalize
        self.job_name = job_name
        self._fault = fault
        self._finalization_deadline = None
        self._data = dict(runId=log_path.parent.name, projectId=project_id, command=command,
                          state="starting", terminal=False, pid=None, createdAt=timestamp(),
                          startedAt=None, finishedAt=None, exitCode=None, error=None,
                          logPath=str(log_path))

    def _set(self, **values):
        with self._lock:
            if self._persist is not None:
                self._persist(values)
            self._data.update(values)

    def snapshot(self):
        with self._lock:
            return {**self._data, "error": dict(self._data["error"]) if self._data["error"] else None}

    def stop(self):
        """Internal/manual cancellation, not a public HTTP cancellation endpoint."""
        self._cancel.set()

    def wait(self, timeout=None):
        if not self._done.wait(timeout):
            raise TimeoutError("The command is still running.")
        if self._failure is not None:
            raise self._failure
        return self.snapshot()


class ProcessExecutor:
    def __init__(self, settings, busy=None, log_root=None):
        self.settings = settings
        self.busy = busy if busy is not None else threading.Lock()
        self.log_root = checked_path(settings.workspace, log_root or
                                     (settings.runtime or settings.staging.parent / "runtime") / "process-runs")
        self._lifecycle = threading.Lock()
        self._active = None
        self._closed = False

    def start(self, project_id, command, *, prepare=None):
        project = self.settings.project
        if not isinstance(command, str) or not command.strip() or "\0" in command or len(command) > 30000:
            raise ApiError(400, "InvalidCommand", "Use a non-empty command without NUL, at most 30000 characters.")
        codecs.lookup(project.console_encoding)
        timeout = self.settings.limits.execution_timeout_seconds
        if isinstance(timeout, bool) or not math.isfinite(timeout) or timeout <= 0:
            raise ValueError("Execution timeout must be finite and positive.")
        with self._lifecycle:
            if self._closed:
                raise ApiError(503, "ExecutorStopped", "Process executor has stopped.")
            if not self.busy.acquire(blocking=False):
                raise ApiError(409, "Busy", "Another modifying operation is in progress.")
            try:
                root = checked_path(self.settings.workspace, project.root)
                if not root.is_dir():
                    raise ApiError(503, "ProjectUnavailable", "Configured project directory is unavailable.")
                if prepare is None:
                    folder = checked_path(self.settings.workspace, self.log_root / str(uuid4()))
                    folder.mkdir(parents=True, exist_ok=False)
                    run = ProcessRun(project_id, command, folder / "output.log")
                else:
                    run = prepare()
                worker = threading.Thread(target=self._work, args=(run, project, timeout),
                                          name="batch-process-" + run.log_path.parent.name, daemon=True)
                worker.start()
                self._active = run
                return run
            except BaseException:
                self.busy.release()
                raise

    def _work(self, run, project, timeout):
        job = None
        reader = None
        read_failed = threading.Event()
        read_errors = []
        state, error, exit_code = "failed", None, None
        extras = {}
        if is_interactive_launcher(run.snapshot()["command"]):
            self._work_interactive(run, project, run.log_path)
            return
        try:
            log_path = checked_path(self.settings.workspace, run.log_path)
            # Exclusive create: diagnostics from another run are never overwritten.
            with log_path.open("x", encoding="utf-8", newline="") as output:
                job = WindowsJob(name=run.job_name) if run.job_name else WindowsJob()
                job.launch(run.snapshot()["command"], checked_path(self.settings.workspace, project.root))
                run._set(state="running", pid=job.pid, startedAt=timestamp())
                run._started.set()
                deadline = time.monotonic() + timeout
                descriptor = job.output_fd

                def drain():
                    try:
                        decoder = codecs.getincrementaldecoder(project.console_encoding)(errors="replace")
                        with os.fdopen(descriptor, "rb", buffering=0) as stream:
                            while block := stream.read(64 * 1024):
                                output.write(decoder.decode(block))
                                output.flush()
                            output.write(decoder.decode(b"", final=True))
                            output.flush()
                    except Exception as exc:
                        read_errors.append(exc)
                        read_failed.set()

                reader = threading.Thread(target=drain, name="batch-output-" + str(job.pid), daemon=True)
                try:
                    reader.start()
                except BaseException:
                    reader = None
                    raise
                job.output_fd = None  # Ownership transferred to the running reader.
                state = "succeeded"
                while job.active_count():
                    if read_failed.is_set():
                        state = "failed"
                        error = dict(code="LogWriteFailed", message=str(read_errors[0]))
                        break
                    if run._cancel.is_set():
                        state = "interrupted"
                        error = dict(code="ExecutionInterrupted", message="Execution was stopped.")
                        break
                    if time.monotonic() >= deadline:
                        state = "timed_out"
                        error = dict(code="ExecutionTimedOut", message="Command execution time limit exceeded.")
                        break
                    run._cancel.wait(0.02)
                if state != "succeeded":
                    job.terminate()
                    while job.active_count():
                        time.sleep(0.01)
                exit_code = job.exit_code()
                run._finalization_deadline = time.monotonic() + self.settings.limits.result_timeout_seconds
                run._set(state="finalizing", exitCode=exit_code)
                # With every job process gone and the parent's write handle closed,
                # EOF is guaranteed; wait for the complete diagnostic tail.
                reader.join()
                if read_errors:
                    state = "failed"
                    error = dict(code="LogWriteFailed", message=str(read_errors[0]))
                else:
                    sync_log(output)
                if time.monotonic() >= run._finalization_deadline:
                    raise TimeoutError("Result collection time limit exceeded.")
                if state == "succeeded" and exit_code:
                    state = "failed"
                    error = dict(code="CommandFailed", message="Command returned a non-zero exit code.")
            if run._finalize is not None:
                extras = run._finalize(state)
        except TimeoutError as exc:
            state = "timed_out"
            error = dict(code="ResultTimedOut", message=str(exc))
        except Exception as exc:
            state = "failed"
            error = dict(code="ExecutionFailed", message=str(exc))
        finally:
            try:
                if job is not None:
                    # Confirm shutdown even if no output reader was started.
                    job.close()
                if reader is not None:
                    reader.join()
            except Exception as exc:
                run._failure = exc
                if run._fault is not None:
                    run._failure = run._fault(exc)
            try:
                if run._failure is None:
                    run._set(state=state, terminal=True, finishedAt=timestamp(), exitCode=exit_code, error=error, **extras)
            except Exception as exc:
                run._failure = exc
            finally:
                if not run._done.is_set():
                    self.busy.release()
                    run._done.set()
                    run._started.set()

    def _work_interactive(self, run, project, log_path):
        job = None
        state, error, exit_code = "failed", None, None
        try:
            log_path = checked_path(self.settings.workspace, log_path)
            # The child may keep stdout open for its lifetime. Use a separate
            # file instead of waiting for EOF on the operation's log pipe.
            raw_path = log_path.with_name("interactive-output.raw")
            with raw_path.open("x+b") as raw:
                job = WindowsJob(name=run.job_name) if run.job_name else WindowsJob()
                job.launch(run.snapshot()["command"], checked_path(self.settings.workspace, project.root), output_file=raw)
                run._set(state="running", pid=job.pid, startedAt=timestamp())
                run._started.set()
                deadline = time.monotonic() + 10
                while time.monotonic() < deadline:
                    if run._cancel.wait(min(0.1, max(0, deadline - time.monotonic()))):
                        state = "interrupted"
                        error = dict(code="ExecutionInterrupted", message="Execution was stopped.")
                        break
                    code = job.poll_exit_code()
                    if code is not None and code != 0:
                        exit_code = code
                        error = dict(code="CommandFailed", message="Command returned a non-zero exit code.")
                        break
                else:
                    state, exit_code = "succeeded", 0
                raw.flush()
                raw.seek(0)
                text = raw.read().decode(project.console_encoding, errors="replace")
                with log_path.open("x", encoding="utf-8", newline="") as output:
                    output.write(text)
                    sync_log(output)
                if state == "succeeded":
                    job.detach()
                if run._finalize is not None:
                    extras = run._finalize(state)
                else:
                    extras = {}
        except Exception as exc:
            state, error, extras = "failed", dict(code="ExecutionFailed", message=str(exc)), {}
        finally:
            try:
                if job is not None:
                    job.close()
                run._set(state=state, terminal=True, finishedAt=timestamp(), exitCode=exit_code, error=error, **extras)
            except Exception as exc:
                run._failure = run._fault(exc) if run._fault is not None else exc
            finally:
                self.busy.release()
                run._done.set()
                run._started.set()

    def close(self):
        with self._lifecycle:
            self._closed = True
            active = self._active
            if active is not None:
                active.stop()
        if active is not None:
            active._done.wait()

    def __enter__(self):
        return self

    def __exit__(self, *_args):
        self.close()
